import re

def entities(doc, scope):
    prod_node = node_by_title(doc, f"{scope}: Products")
    if not prod_node:
        return []
    prods = []
    for row in table_rows(prod_node):
        prod_id = row[1]['product']
        prods.append({"id": prod_id, "description": prod_id})
    return prods

def recorded_end(doc, scope):
    # The daily ledger is always days 1-14. 
    # The Order book table, if present, typically covers days 15-21.
    nodes = scope_nodes(doc, scope)
    max_day = 14
    for node in nodes:
        if "Order book: Orders received and production planned" in node['title']:
            rows = table_rows(node)
            if rows:
                try:
                    # The last row's 'day' column
                    last_day = int(rows[-1][1]['day'])
                    max_day = max(max_day, last_day)
                except (ValueError, KeyError):
                    pass
    return float(max_day)

def inputs(doc, scope):
    inputs_list = []
    nodes = scope_nodes(doc, scope)

    # Product basic info
    prod_node = node_by_title(doc, f"{scope}: Products")
    if prod_node:
        for row_idx, row in table_rows(prod_node):
            p_id = row['product']
            # Weight (constant across time)
            inputs_list.append({
                "id": f"weight_{p_id}",
                "time": None,
                "kind": "weight",
                "entities": [p_id],
                "fields": {"kg_per_unit": float(row['kg per unit'])},
                "src": [prod_node['node_id'], row_idx]
            })
            # Opening Stock (at start of day 1)
            inputs_list.append({
                "id": f"opening_stock_{p_id}",
                "time": 1.0,
                "kind": "opening_stock",
                "entities": [p_id],
                "fields": {"stock": int(row['opening stock'])},
                "src": [prod_node['node_id'], row_idx]
            })

    # Daily ledger (days 1-14)
    ledger_node = node_by_title(doc, f"{scope}: Daily ledger")
    if ledger_node:
        for row_idx, row in table_rows(ledger_node):
            day = float(row['day'])
            p_id = row['product']
            # Production
            if int(row['produced']) > 0:
                inputs_list.append({
                    "id": f"prod_{p_id}_{day}",
                    "time": day,
                    "kind": "production",
                    "entities": [p_id],
                    "fields": {"units": int(row['produced'])},
                    "src": [ledger_node['node_id'], row_idx]
                })
            # Orders
            if int(row['ordered']) > 0:
                inputs_list.append({
                    "id": f"order_{p_id}_{day}",
                    "time": day,
                    "kind": "sales_order",
                    "entities": [p_id],
                    "fields": {"units": int(row['ordered'])},
                    "src": [ledger_node['node_id'], row_idx]
                })

    # Order book (days 15-21)
    for node in nodes:
        if "Order book: Orders received and production planned" in node['title']:
            for row_idx, row in table_rows(node):
                day = float(row['day'])
                p_id = row['product']
                # Planned Production
                if int(row['planned production']) > 0:
                    inputs_list.append({
                        "id": f"plan_prod_{p_id}_{day}",
                        "time": day,
                        "kind": "production",
                        "entities": [p_id],
                        "fields": {"units": int(row['planned production'])},
                        "src": [node['node_id'], row_idx]
                    })
                # Orders
                if int(row['ordered']) > 0:
                    inputs_list.append({
                        "id": f"plan_order_{p_id}_{day}",
                        "time": day,
                        "kind": "sales_order",
                        "entities": [p_id],
                        "fields": {"units": int(row['ordered'])},
                        "src": [node['node_id'], row_idx]
                    })

    return inputs_list

def outcomes(doc, scope):
    outcomes_list = []
    nodes = scope_nodes(doc, scope)

    # Daily ledger results (days 1-14)
    ledger_node = node_by_title(doc, f"{scope}: Daily ledger")
    if ledger_node:
        for row_idx, row in table_rows(ledger_node):
            day = float(row['day'])
            p_id = row['product']
            # Shipped
            outcomes_list.append({
                "time": day,
                "kind": "shipped_quantity",
                "entities": [p_id],
                "value": int(row['shipped']),
                "src": [ledger_node['node_id'], row_idx]
            })
            # Backordered
            outcomes_list.append({
                "time": day,
                "kind": "backordered_quantity",
                "entities": [p_id],
                "value": int(row['backordered']),
                "src": [ledger_node['node_id'], row_idx]
            })
            # Stock
            outcomes_list.append({
                "time": day,
                "kind": "stock_level",
                "entities": [p_id],
                "value": int(row['stock']),
                "src": [ledger_node['node_id'], row_idx]
            })

    # Events
    event_node = node_by_title(doc, f"{scope}: Events")
    if event_node:
        prod_ids = [e['id'] for e in entities(doc, scope)]
        for line_idx, line in enumerate(event_node['lines']):
            # Extract day: "Day 1 (2023-01-01): ..."
            match = re.match(r"Day (\d+)", line)
            if match:
                day = float(match.group(1))
                # Extract entities involved in the event
                involved = [p for p in prod_ids if p in line]
                # Identify event kind
                kind = "generic_event"
                if "dispatch capacity reached" in line:
                    kind = "dispatch_capacity_reached"
                elif "runs out of stock" in line:
                    kind = "out_of_stock"
                elif "fully backordered" in line:
                    kind = "order_fully_backordered"
                elif "backlog is cleared" in line or "backlogs were cleared" in line:
                    kind = "backlog_cleared"

                outcomes_list.append({
                    "time": day,
                    "kind": kind,
                    "entities": involved,
                    "value": None,
                    "src": [event_node['node_id'], line_idx]
                })

    return outcomes_list

def params(doc, scope):
    params_dict = {}
    scope_node = node_by_title(doc, scope)
    if scope_node and scope_node['kind'] == 'text':
        text = scope_node['text']
        cap_match = re.search(r"Daily dispatch capacity: (\d+) kg", text)
        if cap_match:
            params_dict["dispatch_capacity"] = int(cap_match.group(1))
    return params_dict
